		tempCheckpoints, _ := store.ListCheckpointsForBranch(ctx, sb.BranchName, "", limit) //nolint:errcheck // Best-effort
		for _, tc := range tempCheckpoints {
			point := convertTemporaryCheckpoint(repo, tc)
			if point != nil {
				points = append(points, *point)
			}
		}
	}

	return points
}

